31 | // Extract the `const DATA = {...};` object by brace-matching (regex is unsafe on nested braces).
32 | function extractDATA(h) {
33 |   const key = 'const DATA = ';
34 |   const start = h.indexOf(key) + key.length;
35 |   let depth = 0, i = start, inStr = false, q = '', esc = false;
36 |   for (; i < h.length; i++) {
37 |     const c = h[i];
38 |     if (inStr) { if (esc) esc = false; else if (c === '\\') esc = true; else if (c === q) inStr = false; }
39 |     else if (c === '"' || c === "'") { inStr = true; q = c; }
40 |     else if (c === '{') depth++;
41 |     else if (c === '}') { depth--; if (depth === 0) { i++; break; } }
42 |   }
43 |   return JSON.parse(h.slice(start, i));
44 | }
